interface ToggleProps {
  defaultOn?: boolean;
  onChange?: (on: boolean) => void;
  children: (api: ToggleAPI) => React.ReactNode;
}

interface ToggleAPI {
  on: boolean;
  toggle: () => void;
  getToggleProps: (props?: React.ButtonHTMLAttributes<HTMLButtonElement>) => {
    role: 'switch';
    'aria-checked': boolean;
    onClick: () => void;
    onKeyDown: (e: React.KeyboardEvent) => void;
  };
}

function Toggle({ defaultOn = false, onChange, children }: ToggleProps) {
  const [on, setOn] = React.useState(defaultOn);

  const toggle = () => {
    const next = !on;
    setOn(next);
    onChange?.(next);
  };

  const getToggleProps = (extra?: React.ButtonHTMLAttributes<HTMLButtonElement>) => ({
    role: 'switch' as const,
    'aria-checked': on,
    onClick: toggle,
    onKeyDown: (e: React.KeyboardEvent) => {
      if (e.key === ' ' || e.key === 'Enter') {
        e.preventDefault();
        toggle();
      }
    },
    ...extra,
  });

  return children({ on, toggle, getToggleProps });
}

// Usage with fully custom markup
<Toggle defaultOn={false} onChange={(on) => console.log(on)}>
  {({ on, getToggleProps }) => (
    <button {...getToggleProps({ className: on ? 'active' : '' })}>
      {on ? 'ON' : 'OFF'}
    </button>
  )}
</Toggle>

interface UseToggleOptions {
  defaultOn?: boolean;
  onChange?: (on: boolean) => void;
}

interface UseToggleReturn {
  on: boolean;
  toggle: () => void;
  setOn: (on: boolean) => void;
  getButtonProps: (props?: React.ButtonHTMLAttributes<HTMLButtonElement>) => Record<string, unknown>;
}

function useToggle(options: UseToggleOptions = {}): UseToggleReturn {
  const { defaultOn = false, onChange } = options;
  const [on, setOn] = React.useState(defaultOn);

  const toggle = () => {
    const next = !on;
    setOn(next);
    onChange?.(next);
  };

  const getButtonProps = (extra?: React.ButtonHTMLAttributes<HTMLButtonElement>) => ({
    role: 'switch' as const,
    'aria-checked': on,
    onClick: toggle,
    onKeyDown: (e: React.KeyboardEvent) => {
      if (e.key === ' ' || e.key === 'Enter') {
        e.preventDefault();
        toggle();
      }
    },
    ...extra,
  });

  return { on, toggle, setOn, getButtonProps };
}

// Usage in any component
function SettingsRow() {
  const { on, getButtonProps } = useToggle({ defaultOn: true });

  return (
    <div className="setting">
      <span>Notifications</span>
      <button {...getButtonProps({ className: 'toggle' })}>
        {on ? 'Enabled' : 'Disabled'}
      </button>
    </div>
  );
}

